    if(KY.on && HOOK.vehicle) HOOK.vehicleInter=KY.vi; M.fallTex.offset.y=tt*.8; if(M.water.normalMap){ M.water.normalMap.offset.set(tt*.004,tt*.003); } M.portal.opacity=.35+.2*Math.sin(tt*2.2); for(const o of spin){ o.rotation.y+=dt*.8; o.position.y=FY+2.6+.2*Math.sin(tt*1.7+o.position.x); }
    /* trong lòng vực (dưới mực biển) camera của game bị ép lên trên mặt biển → mở khoá bằng camBox theo đúng độ cao mong muốn */
    /* lưới an toàn: lỡ rơi xuống hồ đáy vực (dưới mặt nước) → đưa lên ốc đảo */ if(P.y<LY-1.2 && !HOOK.vehicle && re(P.x,P.z)<.84){ teleport(OC[0],OC[1]+13); toast('🌊 Bạn rơi xuống hồ – đã đưa lên ốc đảo Master Dashboard',2600); }
    const deep=P.y<-1.5 && !W.inside; if(deep){ const want=cam.ty+Math.sin(cam.pitch)*(cam.occ||cam.dist||6); HOOK.camBox={x0:-1e6, x1:1e6, z0:-1e6, z1:1e6, y1:Math.max(want,(P.y<LY+1?LY:P.y)+.5), _ab:true}; } else if(HOOK.camBox && HOOK.camBox._ab) HOOK.camBox=null;
